# name: late_minus_early_yes_rate
# description: Yes-rate on trials with trial_index >= 300 minus yes-rate on trials with trial_index < 150; observed > model means people drift toward "yes" over the session more than the trial-invariant model predicts (observed < model means drift toward "no").
def test_statistic(df):
    t = df["trial_index"].astype(float).values
    r = df["rating"].astype(float).values
    late = t >= 300
    early = t < 150
    if late.sum() == 0 or early.sum() == 0:
        return 0.0
    return float(r[late].mean() - r[early].mean())

# name: cell_consensus_all
# description: Over all (set, target) cells with at least 5 responses, the mean of p*(1-p) where p is the cell's yes-rate; observed < model means people's answers to the same item are more consensual / all-or-none than the model's graded probabilities produce, observed > model means more within-item disagreement than predicted.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["mean", "count"])
    g = g[g["count"] >= 5]
    if len(g) == 0:
        return 0.0
    p = g["mean"].values
    return float(np.mean(p * (1 - p)))

# name: example_target_yes_rate
# description: Yes-rate on trials whose target is one of the shown examples; observed > model means people endorse already-shown examples more reliably than the model (whose guessing dilutes these near-certain items) predicts, observed < model means they endorse them less.
def test_statistic(df):
    s = "," + df["number_set"].astype(str).str.replace(" ", "") + ","
    t = "," + df["target"].astype(int).astype(str) + ","
    mask = np.array([b in a for a, b in zip(s.values, t.values)])
    if mask.sum() == 0:
        return 0.0
    return float(df["rating"].values[mask].mean())
